window.kbPageData["views/entry/k-ff4f281aa7a31b1c"] = {"key":"entry/k-ff4f281aa7a31b1c","state":{"route":"entry/k-ff4f281aa7a31b1c"},"node":{"id":"k-ff4f281aa7a31b1c","mode":"k","title":"渐进式延迟法定退休年龄","type":"制度与规则","domain":"社会治理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["employment"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["社会治理"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2025,"title":"渐进式延迟法定退休年龄","slug":"fb92e0892fc0"}],"directorySummary":"2.渐进式延迟法定退休年龄\n综合考虑我国人均预期寿命、健康水平、人口结构、国民受教育程度、劳动力供给等因\n素，按照小步调整、弹性实施、分类推进、统筹兼顾的原则，实施渐进式延迟法定退休年龄。\n从 2025 年 1 月 1 日起，男职工和原法定退休年龄为五十五周岁的女职工，法定退休年\n龄每四个月延迟一个…","sources":[{"id":"fb268ae88da0ea94","label":"渐进式延迟法定退休年龄","topic":"年度政府工作","category":"时政","text":"2.渐进式延迟法定退休年龄\n综合考虑我国人均预期寿命、健康水平、人口结构、国民受教育程度、劳动力供给等因\n素，按照小步调整、弹性实施、分类推进、统筹兼顾的原则，实施渐进式延迟法定退休年龄。\n从 2025 年 1 月 1 日起，男职工和原法定退休年龄为五十五周岁的女职工，法定退休年\n龄每四个月延迟一个月，分别逐步延迟至六十三周岁和五十八周岁；原法定退休年龄为五十\n周岁的女职工，法定退休年龄每二个月延迟一个月，逐步延迟至五十五周岁。国家另有规定\n的，从其规定。\n从 2030 年 1 月 1 日起，将职工按月领取基本养老金最低缴费年限由十五年逐步提高至\n二十年，每年提高六个月。\n职工达到最低缴费年限，可以自愿选择弹性提前退休，提前时间最长不超过三年，且\n退休年龄不得低于女职工五十周岁、五十五周岁及男职工六十周岁的原法定退休年龄。职工\n达到法定退休年龄，所在单位与职工协商一致的，可以弹性延迟退休，延迟时间最长不超过\n三年。\n——《国务院关于渐进式延迟法定退休年龄的办法》","source":{"doc":"6cbfb01fe723bba64b75","first":10,"last":11,"page":10,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"employment","title":"就业质量与社会保障"}],"units":{"k-ff4f281aa7a31b1c":[]}};
